create table if not exists public.business_engagement_attributions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, business_id uuid references public.businesses(id) on delete set null, location_id uuid, partner_network_id uuid references public.enterprise_partner_networks(id) on delete set null, campaign_id uuid, activity_type text not null, source text not null default 'consumer', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists business_engagement_attr_business_idx on public.business_engagement_attributions(business_id,created_at desc);
create index if not exists business_engagement_attr_network_idx on public.business_engagement_attributions(partner_network_id,created_at desc);
create index if not exists business_engagement_attr_campaign_idx on public.business_engagement_attributions(campaign_id,created_at desc);
alter table public.business_engagement_attributions enable row level security;
create or replace function public.record_business_engagement_attribution(p_business_id uuid default null,p_location_id uuid default null,p_partner_network_id uuid default null,p_campaign_id uuid default null,p_activity_type text default 'engagement',p_source text default 'consumer',p_metadata jsonb default '{}'::jsonb) returns public.business_engagement_attributions language plpgsql security definer set search_path=public as $$ declare a public.business_engagement_attributions; begin if auth.uid() is null then raise exception 'authentication required'; end if; insert into public.business_engagement_attributions(user_id,business_id,location_id,partner_network_id,campaign_id,activity_type,source,metadata) values(auth.uid(),p_business_id,p_location_id,p_partner_network_id,p_campaign_id,p_activity_type,p_source,coalesce(p_metadata,'{}'::jsonb)) returning * into a; return a; end $$;
revoke all on function public.record_business_engagement_attribution(uuid,uuid,uuid,uuid,text,text,jsonb) from public,anon;
grant execute on function public.record_business_engagement_attribution(uuid,uuid,uuid,uuid,text,text,jsonb) to authenticated;
create or replace function public.get_business_engagement_funnel(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns table(activity_type text,source text,events bigint,unique_users bigint) language sql security definer set search_path=public as $$ select activity_type,source,count(*) as events,count(distinct user_id) as unique_users from public.business_engagement_attributions where business_id=p_business_id and created_at between p_start and p_end group by activity_type,source order by count(*) desc $$;
revoke all on function public.get_business_engagement_funnel(uuid,timestamptz,timestamptz) from public,anon;
grant execute on function public.get_business_engagement_funnel(uuid,timestamptz,timestamptz) to authenticated;
